SELECT * FROM sys_oper_log
WHERE 1=1

    AND module = #{module}


    AND operator_name LIKE CONCAT('%', #{operatorName}, '%')


    AND status = #{status}


    AND operation_time >= #{beginTime}


    AND operation_time <= #{endTime}

ORDER BY operation_time DESC
LIMIT #{offset}, #{limit}

SELECT COUNT(*) FROM sys_oper_log
WHERE 1=1

    AND module = #{module}


    AND operator_name LIKE CONCAT('%', #{operatorName}, '%')


    AND status = #{status}


    AND operation_time >= #{beginTime}


    AND operation_time <= #{endTime}
